// news-image-20261120 v3 — entrypoint.
// Copies the pre-built entry.png (generated by compose.py) into the
// make.fun output directory, validating it first. Node 22 stdlib only.
import { copyFileSync, mkdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const SRC = join(HERE, "entry.png");
const OUT_DIR = process.env.MAKEFUN_OUTPUT_DIR || "/output";
const DEST = join(OUT_DIR, "entry.png");

const MAX_BYTES = 1024 * 1024; // 1 MiB
const MAX_DIM = 1024;

const PNG_MAGIC = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

function fail(message: string): never {
  console.error(`entry validation failed: ${message}`);
  process.exit(1);
}

const stat = statSync(SRC);
if (stat.size > MAX_BYTES) {
  fail(`entry.png is ${stat.size} bytes, over the ${MAX_BYTES} byte limit`);
}

const buf = readFileSync(SRC);
if (buf.length < 33 || !buf.subarray(0, 8).equals(PNG_MAGIC)) {
  fail("entry.png is not a PNG (bad signature)");
}
// First chunk must be IHDR (bytes 12-15) so the dimension fields are real.
if (buf.subarray(12, 16).toString("ascii") !== "IHDR") {
  fail("entry.png has no IHDR chunk where one is expected");
}
// IHDR: width at bytes 16-19, height at bytes 20-23, big-endian uint32.
const width = buf.readUInt32BE(16);
const height = buf.readUInt32BE(20);
if (width > MAX_DIM || height > MAX_DIM) {
  fail(`entry.png is ${width}x${height}, over the ${MAX_DIM}px limit`);
}

mkdirSync(OUT_DIR, { recursive: true });
copyFileSync(SRC, DEST);
console.log(
  `copied entry.png (${stat.size} bytes, ${width}x${height}) -> ${DEST}`,
);
